﻿import { types } from 'mobx-state-tree';

export const TimeEntryModel = types.model('TimeEntry', {
    id: types.identifier,
    employeeId: types.string,
    projectId: types.string,
    date: types.string, // ISO string
    hours: types.number,
    comment: types.maybe(types.string),
    createdBy: types.maybe(types.string),
    createdAt: types.maybe(types.string),
    modifiedBy: types.maybe(types.string),
    modifiedAt: types.maybe(types.string),
    version: types.optional(types.number, 1)
});

export type TimeEntryModelType = typeof TimeEntryModel.Type;