﻿import React, { useEffect, useState, useMemo } from 'react';
import { AgGridReact } from 'ag-grid-react';
import { Button } from '@blueprintjs/core';
import 'ag-grid-community/dist/styles/ag-grid.css';
import 'ag-grid-community/dist/styles/ag-theme-alpine.css';
import * as api from '../utils/api';

type TimeEntryRow = {
    id: string;
    employeeId: string;
    projectId: string;
    date: string; // ISO
    hours: number;
    comment?: string;
    createdBy?: string;
    createdAt?: string;
    modifiedBy?: string;
    modifiedAt?: string | null;
    version?: number;
};

type Props = {
    onClose?: () => void;
};

const TimeEntryList: React.FC<Props> = ({ onClose }) => {
    const [rows, setRows] = useState<TimeEntryRow[]>([]);
    const [loading, setLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        let mounted = true;
        const load = async () => {
            setLoading(true);
            setError(null);
            try {
                const data = await api.fetchTimeEntries();
                if (mounted) {
                    // Приводим к ожидаемой форме (минимальная адаптация)
                    const normalized = (data ?? []).map((x: any) => ({
                        id: x.id ?? x._id ?? '',
                        employeeId: x.employeeId ?? '',
                        projectId: x.projectId ?? '',
                        date: x.date ?? x.Date ?? '',
                        hours: x.hours ?? x.Hours ?? 0,
                        comment: x.comment ?? x.Comment ?? '',
                        createdBy: x.createdBy ?? x.CreatedBy ?? '',
                        createdAt: x.createdAt ?? x.CreatedAt ?? '',
                        modifiedBy: x.modifiedBy ?? x.ModifiedBy ?? '',
                        modifiedAt: x.modifiedAt ?? x.ModifiedAt ?? null,
                        version: x.version ?? x.Version ?? 0
                    }));
                    setRows(normalized);
                }
            } catch (e: any) {
                setError(e?.message ?? 'Ошибка при загрузке записей табеля');
            } finally {
                setLoading(false);
            }
        };

        load();
        return () => { mounted = false; };
    }, []);

    const columnDefs = useMemo(() => [
        { headerName: 'ID', field: 'id', hide: true },
        { headerName: 'Сотрудник', field: 'employeeId', sortable: true, filter: true, flex: 1 },
        { headerName: 'Проект', field: 'projectId', sortable: true, filter: true, flex: 1 },
        {
            headerName: 'Дата', field: 'date', sortable: true, filter: true, width: 140,
            valueFormatter: (params: any) => params.value ? new Date(params.value).toLocaleDateString() : ''
        },
        { headerName: 'Часы', field: 'hours', sortable: true, filter: true, width: 100 },
        { headerName: 'Комментарий', field: 'comment', flex: 2 },
        { headerName: 'Создал', field: 'createdBy', width: 140 },
        { headerName: 'Версия', field: 'version', width: 100 }
    ], []);

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
                <Button minimal onClick={() => { /* можно добавить refresh */ window.location.reload(); }}>
                    Обновить
                </Button>
                <Button intent="primary" onClick={() => onClose?.()}>
                    Закрыть
                </Button>
            </div>

            {loading && <div>Загрузка...</div>}
            {error && <div style={{ color: 'red' }}>{error}</div>}

            {!loading && !error && (
                <div className="ag-theme-alpine" style={{ height: 480, width: '100%' }}>
                    <AgGridReact
                        rowData={rows}
                        columnDefs={columnDefs}
                        pagination={true}
                        paginationPageSize={25}
                        defaultColDef={{ resizable: true }}
                    />
                </div>
            )}
        </div>
    );
};

export default TimeEntryList;