﻿import { types, flow, Instance } from 'mobx-state-tree';
import { TimeEntryModel, TimeEntryModelType } from './timeEntryStore';
import * as api from '../utils/api';

const RootStore = types
    .model('RootStore', {
        timesheets: types.array(TimeEntryModel),
        lastError: types.maybeNull(types.string),
        loading: types.optional(types.boolean, false)
    })
    .actions(self => {
        const fetchTimeEntry = flow(function* () {
            self.loading = true;
            try {
                const data = yield api.fetchTimeEntries();
                self.timeEntry.clear();
                (data ?? []).forEach((t: any) =>
                    self.timeEntry.push({
                        id: t.id ?? t._id ?? '',
                        employeeId: t.employeeId ?? '',
                        projectId: t.projectId ?? '',
                        date: t.date ?? t.Date ?? '',
                        hours: t.hours ?? t.Hours ?? 0,
                        comment: t.comment ?? t.Comment ?? '',
                        createdBy: t.createdBy ?? t.CreatedBy ?? '',
                        createdAt: t.createdAt ?? t.CreatedAt ?? '',
                        modifiedBy: t.modifiedBy ?? t.ModifiedBy ?? '',
                        modifiedAt: t.modifiedAt ?? t.ModifiedAt ?? null,
                        version: t.version ?? t.Version ?? 1
                    } as TimeEntryModelType)
                );
                self.lastError = null;
            } catch (err: any) {
                self.timeEntry.clear();
                self.lastError = err?.message ?? 'Ошибка при загрузке записей табеля';
            } finally {
                self.loading = false;
            }
        });

        const createTimeEntry = flow(function* (payload: any) {
            try {
                // API должен возвращать созданный id или объект
                const res = yield api.createTimeEntry ? api.createTimeEntry(payload) : api.createTimeEntryFallback(payload);
                // после успешного создания — перезагрузим список
                yield fetchTimeEntries();
                return res;
            } catch (err: any) {
                self.lastError = err?.message ?? 'Ошибка при создании записи табеля';
                throw err;
            }
        });

        const updateTimeEntry = flow(function* (id: string, payload: any) {
            try {
                const res = yield api.updateTimeEntry ? api.updateTimeEntry(id, payload) : api.updateTimeEntryFallback(id, payload);
                yield fetchTimeEntries();
                return res;
            } catch (err: any) {
                self.lastError = err?.message ?? 'Ошибка при обновлении записи табеля';
                throw err;
            }
        });

        const deleteTimeEntry = flow(function* (id: string) {
            try {
                const res = yield api.deleteTimeEntry ? api.deleteTimeEntry(id) : api.deleteTimeEntryFallback(id);
                yield fetchTimeEntries();
                return res;
            } catch (err: any) {
                self.lastError = err?.message ?? 'Ошибка при удалении записи табеля';
                throw err;
            }
        });

        return { fetchTimeEntry, createTimeEntry, updateTimeEntry, deleteTimeEntry };
    });

export function createRootStore() {
    const store = RootStore.create({ timeEntry: [] as any, lastError: null, loading: false });
    // стартовая загрузка
    (store as any).fetchTimeEntries();
    return store;
}

export type RootStore = Instance<typeof RootStore>;